.toast-avatar {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  overflow: hidden;
  border: 2px solid white; /* inner ring */
  box-shadow: 0 0 0 2px #4f46e5; /* outer blue ring */
}

.toast-avatar img {
  width: 100%;
  height: 100%;
  border-radius: 50%;
  object-fit: cover;
}
